<?php
namespace Tests\Feature;
use App\Models\ContractTemplate; use App\Models\ContractTemplateVersion; use App\Models\ContractType; use App\Models\Customer; use App\Models\Language; use App\Models\Role; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Laravel\Sanctum\Sanctum; use Tests\TestCase;
class VersionedContractGenerationTest extends TestCase { use RefreshDatabase; protected function setUp(): void { parent::setUp(); $u=User::factory()->create();$u->roles()->attach(Role::firstOrCreate(['name'=>'super_admin']));Sanctum::actingAs($u,['access']); }
 public function test_contract_uses_the_active_template_version_and_keeps_snapshot(): void { $type=ContractType::where('slug','customer')->firstOrFail();$template=ContractTemplate::create(['name'=>'Agreement','contract_type_id'=>$type->id,'cover_text'=>'','content'=>'<p>old</p>']);$language=Language::create(['name'=>'English','code'=>'en']);$version=ContractTemplateVersion::create(['contract_template_id'=>$template->id,'language_id'=>$language->id,'version_number'=>1,'content'=>'<p>{{customer.name}} v1</p>','status'=>'active','is_current'=>true]);$customer=Customer::factory()->create();$this->postJson('/api/contracts',['template_id'=>$template->id,'customer_id'=>$customer->id,'status'=>'active','start_date'=>'2026-09-17'])->assertCreated()->assertJsonPath('data.contract_template_version_id',$version->id)->assertJsonPath('data.content',"<p>{$customer->name} v1</p>"); } }
